	data.config
	now_ns := object.get(data.config, ["policy", "when_ns"], time.now_ns())

newest(items) := item if {
	ordered := arrays.sort_by("effective_on", items)

	item := ordered[count(ordered) - 1]

validate_schema(doc, schema) := issues if {
	count(_arg_issues(doc, schema)) == 0
	issues := _validation_issues(doc, schema)
} else := _arg_issues(doc, schema)

le(left, right) := is_le if {
	type_name(left) == type_name(right)
	is_le := left <= right
